function hasAll(env, requiredKeys) {
  return requiredKeys.every((key) => Boolean(env[key]));
}

function firstMissing(env, requiredKeys) {
  for (const key of requiredKeys) {
    if (!env[key]) return key;
  }
  return null;
}

function requireEnv(env, name) {
  const value = env[name];
  if (!value) throw new Error('Missing ' + name);
  return value;
}

function presentKeys(env, requiredKeys) {
  return requiredKeys.filter((key) => Boolean(env[key]));
}

function isSet(env, name) {
  return typeof env[name] === 'string' && env[name].length > 0;
}

function missingMessage(env, requiredKeys) {
  const missing = requiredKeys.filter((key) => !env[key]);
  return missing.length === 0 ? '' : 'Missing: ' + missing.join(', ');
}

function missingKeys(env, requiredKeys) {
  return requiredKeys.filter((key) => !env[key] || env[key].trim() === '');
}

function validateConfig(env, requiredKeys) {
  const missing = requiredKeys.filter((key) => !env[key]);
  return { ok: missing.length === 0, missing: missing };
}

function assertConfig(env, requiredKeys) {
  const missing = requiredKeys.filter((key) => !env[key]);
  if (missing.length > 0) throw new Error('Missing: ' + missing.join(', '));
  return true;
}
